function rotate(nums: number[], k: number): void {
  const n = nums.length;
  k = k % n;

  const reverse = (arr: number[], start: number, end: number) => {
    while (start < end) {
      [arr[start], arr[end]] = [arr[end], arr[start]];
      start++;
      end--;
    }
  };

  reverse(nums, 0, n - 1);
  reverse(nums, 0, k - 1);
  reverse(nums, k, n - 1);
}

// Time Complexity: O(n)
// Space Complexity: O(1)
